    { name = 'Bonecraft', group = 'Crafting', desc = 'In each band, synthesize one of these until it stops giving skill, then move on. Cheapest first, using Olympus XI\'s own recipes and shop prices; ingredients any new player can buy are preferred over ones a guild sells only at a higher craft rank. Merchant prices are base prices (nation fame can move some of them a little); guild shop prices are the most they charge.', steps = {
            { title = 'Bonecraft 0–10', note = '• Bone Hairpin (cap 4): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil)\n• Bone Arrowhd. (cap 10): Wind Crystal + 2 × Bone Chip (Retto-Marutto, Windurst Woods, 150 gil)\n• Shell Ring (cap 7): Wind Crystal + Fish Scales (Retto-Marutto, Windurst Woods, 96 gil), Seashell (Shih Tayuun, Windurst Woods, 600 gil)\n• Shell Earring (cap 3): Wind Crystal + 2 × Seashell (Shih Tayuun, Windurst Woods, 600 gil)' },
            { title = 'Bonecraft 10–20', note = '• Gelatin (cap 13): Fire Crystal + 2 × Chicken Bone (Shih Tayuun, Windurst Woods, 200 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Bone Ring (cap 17): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Sheep Tooth (Shih Tayuun, Windurst Woods, 1000 gil)\n• Bone Earring (cap 12), also needs Goldsmithing 3: Wind Crystal + Brass Ingot (Bornahn, Al Zahbi, 1000 gil), 2 × Bone Chip (Retto-Marutto, Windurst Woods, 150 gil)\n• Bone Mittens (cap 20), also needs Leathercraft 5: Earth Crystal + 2 × Sheep Leather (Kueh Igunahmori, Southern San d\'Oria, 1000 gil), 2 × Bone Chip (Retto-Marutto, Windurst Woods, 150 gil)' },
            { title = 'Bonecraft 20–30', note = '• Beetle Ring (cap 25): Wind Crystal + Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil)\n• Carap. Powder (cap 21): Wind Crystal + 2 × Beetle Shell (Shih Tayuun, Windurst Woods, 1625 gil)\n• Bone Subligar (cap 24), also needs Leathercraft 6: Earth Crystal + Grass Cloth (Kuzah Hpirohpon, Windurst Woods, 1600 gil), 2 × Sheep Leather (Kueh Igunahmori, Southern San d\'Oria, 1000 gil), Bone Chip (Retto-Marutto, Windurst Woods, 150 gil)\n• Beetle Earring (cap 27): Earth Crystal + Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil), Silver Earring (Adelflete, Lower Jeuno, 1250 gil)' },
            { title = 'Bonecraft 30–40', note = '• Beetle Arrowhd. (cap 33): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil)\n• Bone Cudgel (cap 40): Wind Crystal + Grass Cloth (Kuzah Hpirohpon, Windurst Woods, 1600 gil), 6 × Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil)\n• Beetle Gorget (cap 31): Earth Crystal + Beetle Shell (Shih Tayuun, Windurst Woods, 1625 gil), 2 × Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil)\n• Beetle Subligar (cap 34), also needs Leathercraft 9: Earth Crystal + Cotton Cloth (Kuzah Hpirohpon, Windurst Woods, 3200 gil), Lizard Skin (Kueh Igunahmori, Southern San d\'Oria, 1625 gil), Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil)' },
            { title = 'Bonecraft 40–50', note = '• Bone Knife (cap 41): Wind Crystal + Walnut Lumber (Chaupire, Northern San d\'Oria, 4880 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil)\n• Horn Arrowheads (cap 43): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Ram Horn (Shih Tayuun, Windurst Woods, 18000 gil)\n• Horn (cap 47): Wind Crystal + Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil), Ram Horn (Shih Tayuun, Windurst Woods, 18000 gil)\n• Carapace Mask (cap 45): Earth Crystal + Dhalmel Leather (Kueh Igunahmori, Southern San d\'Oria, 11650 gil), Crab Shell (Shih Tayuun, Windurst Woods, 11490 gil)' },
            { title = 'Bonecraft 50–60', note = '• Blood Stone (cap 57): Wind Crystal + Grass Thread (Kuzah Hpirohpon, Windurst Woods, 300 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil), Fiend Blood (Pahya Lolohoiv, Kazham, 605 gil)\n• Scp. Arrowhd. (cap 53): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Scorpion Claw (Shih Tayuun, Windurst Woods, 8190 gil)\n• Scorpion Ring (cap 60): Wind Crystal + Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)\n• Bone Scythe (cap 57), also needs Woodworking 19: Wind Crystal + Yew Lumber (Chaupire, Northern San d\'Oria, 2200 gil), Grass Cloth (Kuzah Hpirohpon, Windurst Woods, 1600 gil), Sheep Tooth (Shih Tayuun, Windurst Woods, 1000 gil), 2 × Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil)' },
            { title = 'Bonecraft 60–70', note = '• Bone Patas (cap 68): Fire Crystal + Crab Shell (Shih Tayuun, Windurst Woods, 11490 gil), 2 × Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil), Carbon Fiber (Gathweeda, Aht Urhgan Whitegate, 6000 gil)\n• Scorpion Mask (cap 64): Earth Crystal + Ram Leather (Kueh Igunahmori, Southern San d\'Oria, 18120 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)\n• Beast Horn (cap 69): Wind Crystal + 2 × Ram Horn (Shih Tayuun, Windurst Woods, 18000 gil)\n• Scorpion Subligar (cap 67), also needs Leathercraft 32: Earth Crystal + Linen Cloth (Kuzah Hpirohpon, Windurst Woods, 15000 gil), Ram Leather (Kueh Igunahmori, Southern San d\'Oria, 18120 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)' },
            { title = 'Bonecraft 70–80', note = '• M. Tusk Arwhds. (cap 78): Wind Crystal + Bone Chip (Retto-Marutto, Windurst Woods, 150 gil), Marid Tusk (Retto-Marutto, Windurst Woods, 4500 gil, sold only to guild rank Craftsman or higher)\n• Tigerfangs (cap 79): Fire Crystal + 2 × Blk. Tiger Fang (Shih Tayuun, Windurst Woods, 12900 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil), Carbon Fiber (Gathweeda, Aht Urhgan Whitegate, 6000 gil)\n• Hornet Fleuret (cap 71), also needs Goldsmithing 52: Fire Crystal + Brass Ingot (Bornahn, Al Zahbi, 1000 gil), Pearl (Celestina, Mhaura, 11000 gil, sold only to guild rank Apprentice or higher), Moonstone (Bornahn, Al Zahbi, 156000 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil), Giant Stinger (Gathweeda, Aht Urhgan Whitegate, 4050 gil)\n• Coral Ring (cap 80): Wind Crystal + 2 × Coral Fragment' },
            { title = 'Bonecraft 80–90', note = '• Marid Ring (cap 81): Wind Crystal + 2 × Marid Tusk (Retto-Marutto, Windurst Woods, 4500 gil, sold only to guild rank Craftsman or higher)\n• Wivre Hairpin (cap 85): Wind Crystal + Wivre Maul\n• Behemoth Ring (cap 89): Wind Crystal + 2 × Behemoth Horn\n• Saintly Ring (cap 81): Earth Crystal + Fish Scales (Retto-Marutto, Windurst Woods, 96 gil), Ascetic\'s Ring' },
            { title = 'Bonecraft 90–100', note = '• Mammoth Tusk (cap 94): Wind Crystal + Giant Frozen Head\n• Cerberus Ring (cap 98): Wind Crystal + 2 × Cerberus Claw\n• Dragon Ring (cap 99): Wind Crystal + 2 × Dragon Talon\n• Chronos Tooth (cap 100): Wind Crystal + Colossal Skull' },
            { title = 'Bonecraft 100–110', note = '• Hades Sainti (cap 101), also needs Woodworking 49, Smithing 37: Wind Crystal + 2 × Iron Ingot (Amulya, Metalworks, 18000 gil), Bldwd. Lumber (Dehbi Moshal, Al Zahbi, 61200 gil), 2 × Cerberus Claw\n• Unicorn Harness (cap 102), also needs Leathercraft 60: Earth Crystal + Gold Thread (Kuzah Hpirohpon, Windurst Woods, 114000 gil), Tiger Leather (Kueh Igunahmori, Southern San d\'Oria, 23040 gil), Behem. Leather, 2 × Unicorn Horn\n• Gavial Mail (cap 103), also needs Leathercraft 27: Earth Crystal + Rainbow Thread (Kuzah Hpirohpon, Windurst Woods, 277200 gil), Sheep Leather (Kueh Igunahmori, Southern San d\'Oria, 1000 gil), 2 × Titanictus Shell, 2 × H.Q. Pugil Scls., Leather Vest (Graine, Mhaura, 671 gil)\n• Hydra Mail (cap 104): Earth Crystal + Rainbow Thread (Kuzah Hpirohpon, Windurst Woods, 277200 gil), Karakul Leather, 2 × Titanictus Shell, 2 × Hydra Scale, Leather Vest (Graine, Mhaura, 671 gil)' }
    } },
    { name = 'Alchemy', group = 'Crafting', desc = 'In each band, synthesize one of these until it stops giving skill, then move on. Cheapest first, using Olympus XI\'s own recipes and shop prices; ingredients any new player can buy are preferred over ones a guild sells only at a higher craft rank. Merchant prices are base prices (nation fame can move some of them a little); guild shop prices are the most they charge.', steps = {
            { title = 'Alchemy 0–10', note = '• Tsurara (cap 6): Ice Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), 2 × Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Cornstarch (cap 9): Lightng. Crystal + 2 × Millioncorn (Benaige, Southern San d\'Oria, 48 gil)\n• Beeswax (cap 5): Fire Crystal + 3 × Beehive Chip (Odoba, Bastok Mines, 40 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Antidote (cap 3): Water Crystal + Wijnruit (Areebah, Upper Jeuno, 120 gil), San d\'Or. Grape (Aveline, Southern San d\'Oria, 76 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)' },
            { title = 'Alchemy 10–20', note = '• Cornstarch (cap 19): Lightng. Crystal + 8 × Millioncorn (Benaige, Southern San d\'Oria, 48 gil)\n• Mercury (cap 16): Lightng. Crystal + 4 × Cobalt Jellyfish (Babubu, Port Windurst, 160 gil)\n• Echo Drops (cap 20): Water Crystal + Sage (Aveline, Southern San d\'Oria, 185 gil), Honey (Kopopo, Windurst Waters, 600 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Poison Dust (cap 12): Lightng. Crystal + 2 × Yellow Globe (Babubu, Port Windurst, 400 gil)' },
            { title = 'Alchemy 20–30', note = '• Eye Drops (cap 30): Water Crystal + Chamomile (Areebah, Upper Jeuno, 130 gil), Ahriman Tears (Odoba, Bastok Mines, 200 gil, sold only to guild rank Initiate or higher), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Baking Soda (cap 22): Lightng. Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Moval. Water (Bartabaq, Oldton Movalpolos, 800 gil)\n• Silent Oil (cap 29): Water Crystal + Olive Oil (Aveline, Southern San d\'Oria, 15 gil), 2 × Beeswax (Gathweeda, Aht Urhgan Whitegate, 600 gil)\n• Vrml. Lacquer (cap 24): Fire Crystal + Mercury (Odoba, Bastok Mines, 1700 gil), Sulfur (Apairemant, Southern San d\'Oria, 803 gil)' },
            { title = 'Alchemy 30–40', note = '• Firesand (cap 40): Earth Crystal + 2 × Bomb Ash (Olaf, Metalworks, 515 gil), Sulfur (Apairemant, Southern San d\'Oria, 803 gil)\n• Blind Dagger (cap 32): Water Crystal + Animal Glue (Gathweeda, Aht Urhgan Whitegate, 600 gil), Blinding Potion (Scamplix, Rabao, 1200 gil), Bronze Dagger (Ashene, Southern San d\'Oria, 156 gil)\n• Blind Knife (cap 34): Water Crystal + Animal Glue (Gathweeda, Aht Urhgan Whitegate, 600 gil), Blinding Potion (Scamplix, Rabao, 1200 gil), Bronze Knife (Kahah Hobichai, Al Zahbi, 164 gil)\n• Bln. Bolt Heads (cap 31), also needs Smithing 14: Wind Crystal + Bronze Ingot (Amulya, Metalworks, 380 gil), Animal Glue (Gathweeda, Aht Urhgan Whitegate, 600 gil), Blinding Potion (Scamplix, Rabao, 1200 gil)' },
            { title = 'Alchemy 40–50', note = '• Carbon Fiber (cap 45): Lightng. Crystal + 4 × Bomb Ash (Olaf, Metalworks, 515 gil)\n• Ether (cap 50): Water Crystal + Dried Marjoram (Dohdjuma, Selbina, 40 gil), 2 × Bat Wing (Gathweeda, Aht Urhgan Whitegate, 300 gil), Dryad Root (Odoba, Bastok Mines, 1800 gil, sold only to guild rank Apprentice or higher), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Acid Bolt Heads (cap 45), also needs Smithing 14: Wind Crystal + Bronze Ingot (Amulya, Metalworks, 380 gil), Animal Glue (Gathweeda, Aht Urhgan Whitegate, 600 gil), Vitriol (Gathweeda, Aht Urhgan Whitegate, 2400 gil)\n• Worm Lure (cap 46), also needs Goldsmithing 12: Fire Crystal + Brass Ingot (Bornahn, Al Zahbi, 1000 gil), Glass Fiber (Gathweeda, Aht Urhgan Whitegate, 4000 gil), Little Worm (Dwago, Aht Urhgan Whitegate, 4 gil)' },
            { title = 'Alchemy 50–60', note = '• Holy Water (cap 51): Light Crystal + Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Earth Arrowhds. (cap 57), also needs Bonecraft 44: Earth Crystal + Copper Ingot (Bornahn, Al Zahbi, 600 gil), Marid Tusk (Retto-Marutto, Windurst Woods, 4500 gil, sold only to guild rank Craftsman or higher)\n• Holy Bolt Heads (cap 53), also needs Smithing 14: Wind Crystal + Bronze Ingot (Amulya, Metalworks, 380 gil), 2 × Holy Water (Attarena, Northern San d\'Oria, 3016 gil)\n• Wind Arrowhds. (cap 57), also needs Bonecraft 35: Wind Crystal + Copper Ingot (Bornahn, Al Zahbi, 600 gil), Colibri Beak (Gathweeda, Aht Urhgan Whitegate, 6250 gil)' },
            { title = 'Alchemy 60–70', note = '• Venom Dust (cap 62): Lightng. Crystal + 2 × Ogre Eel (Babubu, Port Windurst, 800 gil)\n• Ebonite (cap 63): Lightng. Crystal + Sulfur (Apairemant, Southern San d\'Oria, 803 gil), 2 × Flan Meat (Gathweeda, Aht Urhgan Whitegate, 700 gil)\n• Venom Potion (cap 68): Water Crystal + Mercury (Odoba, Bastok Mines, 1700 gil), Venom Dust (Stinknix, Lower Jeuno, 1035 gil)\n• Hi-Ether (cap 69): Water Crystal + 2 × Dried Marjoram (Dohdjuma, Selbina, 40 gil), 4 × Bat Wing (Gathweeda, Aht Urhgan Whitegate, 300 gil), Dryad Root (Odoba, Bastok Mines, 1800 gil, sold only to guild rank Apprentice or higher), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)' },
            { title = 'Alchemy 70–80', note = '• High Ebonite (cap 73): Lightng. Crystal + Sulfur (Apairemant, Southern San d\'Oria, 803 gil), 3 × Flan Meat (Gathweeda, Aht Urhgan Whitegate, 700 gil)\n• Paralyze Potion (cap 78): Water Crystal + Mercury (Odoba, Bastok Mines, 1700 gil), Paralysis Dust (Stinknix, Lower Jeuno, 2000 gil)\n• Spartan Bullet (cap 71), also needs Smithing 13: Fire Crystal + Copper Ingot (Bornahn, Al Zahbi, 600 gil), Bronze Ingot (Amulya, Metalworks, 380 gil), Firesand (Gathweeda, Aht Urhgan Whitegate, 22400 gil), Twinkle Powder (Upih Khachla, Windurst Waters, 385 gil)\n• Air Rider (cap 78), also needs Woodworking 45: Earth Crystal + Lauan Lumber (Chaupire, Northern San d\'Oria, 180 gil), 2 × Firesand (Gathweeda, Aht Urhgan Whitegate, 22400 gil), Bast Parchment (Jabbar, Port Bastok, 5400 gil), Goblin Doll (Bartabaq, Oldton Movalpolos, 500 gil), Twinkle Powder (Upih Khachla, Windurst Waters, 385 gil)' },
            { title = 'Alchemy 80–90', note = '• Polyflan (cap 83): Lightng. Crystal + Flan Meat (Gathweeda, Aht Urhgan Whitegate, 700 gil), Chimera Blood (Gathweeda, Aht Urhgan Whitegate, 7200 gil)\n• Holy Leather (cap 87): Light Crystal + Ram Leather (Kueh Igunahmori, Southern San d\'Oria, 18120 gil), Holy Water (Attarena, Northern San d\'Oria, 3016 gil)\n• Ouka Ranman (cap 84), also needs Woodworking 23: Earth Crystal + Firesand (Gathweeda, Aht Urhgan Whitegate, 22400 gil), Amaryllis (Areebah, Upper Jeuno, 120 gil), 2 × Bast Parchment (Jabbar, Port Bastok, 5400 gil)\n• Comp. Fishing Rod (cap 89): Fire Crystal + 2 × Cermet Chunk (Gathweeda, Aht Urhgan Whitegate, 20000 gil), 3 × Carbon Fiber (Gathweeda, Aht Urhgan Whitegate, 6000 gil), 2 × Glass Fiber (Gathweeda, Aht Urhgan Whitegate, 4000 gil)' },
            { title = 'Alchemy 90–100', note = '• Icarus Wing (cap 93): Wind Crystal + 6 × Giant Bird Fthr. (Kuzah Hpirohpon, Windurst Woods, 4590 gil), 2 × Beeswax (Gathweeda, Aht Urhgan Whitegate, 600 gil)\n• Cannon Shell (cap 94), also needs Smithing 34, Goldsmithing 18: Fire Crystal + Brass Ingot (Bornahn, Al Zahbi, 1000 gil), Iron Ingot (Amulya, Metalworks, 18000 gil), 2 × Firesand (Gathweeda, Aht Urhgan Whitegate, 22400 gil), Bomb Arm (Nogga, Metalworks, 750 gil)\n• Platinum Bullet (cap 95), also needs Goldsmithing 48: Fire Crystal + Platinum Ingot (Bornahn, Al Zahbi, 292500 gil), Firesand (Gathweeda, Aht Urhgan Whitegate, 22400 gil)\n• Ice Lance (cap 93): Ice Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Cermet Lance' },
            { title = 'Alchemy 100–110', note = '• Gold Algol (cap 101), also needs Goldsmithing 60: Fire Crystal + Divine Lumber, 2 × Gold Ingot (Bornahn, Al Zahbi, 115500 gil), 4 × Super Cermet, Scintillant Ingot' }
    } },
    { name = 'Cooking', group = 'Crafting', desc = 'In each band, synthesize one of these until it stops giving skill, then move on. Cheapest first, using Olympus XI\'s own recipes and shop prices; ingredients any new player can buy are preferred over ones a guild sells only at a higher craft rank. Merchant prices are base prices (nation fame can move some of them a little); guild shop prices are the most they charge.', steps = {
            { title = 'Cooking 0–10', note = '• Peeled Crayfish (cap 3): Wind Crystal + Crayfish (Kulh Amariyo, Aht Urhgan Whitegate, 38 gil)\n• Roasted Corn (cap 2): Fire Crystal + Millioncorn (Benaige, Southern San d\'Oria, 48 gil)\n• Boiled Crayfish (cap 9): Fire Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Crayfish (Kulh Amariyo, Aht Urhgan Whitegate, 38 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Hard-boiled Egg (cap 6): Fire Crystal + Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Bird Egg (Denvihr, Port Bastok, 55 gil)' },
            { title = 'Cooking 10–20', note = '• Selbina Butter (cap 20): Ice Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Selbina Milk (Dohdjuma, Selbina, 61 gil)\n• Tortilla (cap 14): Fire Crystal + San d\'Or. Flour (Komalata, Tavnazian Safehold, 60 gil), Millioncorn (Benaige, Southern San d\'Oria, 48 gil), Olive Oil (Aveline, Southern San d\'Oria, 15 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil)\n• Sliced Sardine (cap 11): Wind Crystal + Hamsi (Jidwahn, Silver Sea route to Nashmau, 140 gil)\n• Pet Food Beta (cap 19): Earth Crystal + Horo Flour (Pawkrix, Lower Jeuno, 40 gil), G. Sheep Meat (Bin Stejihna, Windurst Woods, 50 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Bird Egg (Denvihr, Port Bastok, 55 gil)' },
            { title = 'Cooking 20–30', note = '• Insect Ball (cap 29): Earth Crystal + Millioncorn (Benaige, Southern San d\'Oria, 48 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Little Worm (Dwago, Aht Urhgan Whitegate, 4 gil)\n• Soy Milk (cap 21): Fire Crystal + 2 × Blue Peas (Machielle, Southern San d\'Oria, 29 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Meat Jerky (cap 26): Ice Crystal + Dried Marjoram (Dohdjuma, Selbina, 40 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), G. Sheep Meat (Bin Stejihna, Windurst Woods, 50 gil)\n• Pineapple Juice (cap 30): Water Crystal + 2 × Kazham Pineapl. (Ghemi Sinterilo, Kazham, 60 gil)' },
            { title = 'Cooking 30–40', note = '• Black Bread (cap 34): Fire Crystal + Rye Flour (Benaige, Southern San d\'Oria, 40 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Iron Bread (cap 34): Fire Crystal + San d\'Or. Flour (Komalata, Tavnazian Safehold, 60 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Roast Trout (cap 32): Fire Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Alabaligi (Kulh Amariyo, Aht Urhgan Whitegate, 130 gil)\n• Trout Ball (cap 33): Earth Crystal + Rye Flour (Benaige, Southern San d\'Oria, 40 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Alabaligi (Kulh Amariyo, Aht Urhgan Whitegate, 130 gil)' },
            { title = 'Cooking 40–50', note = '• Tomato Juice (cap 43): Water Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), 3 × Mithran Tomato (Ghemi Sinterilo, Kazham, 40 gil)\n• Grape Juice (cap 50): Dark Crystal + 4 × San d\'Or. Grape (Aveline, Southern San d\'Oria, 76 gil)\n• Pie Dough (cap 42): Water Crystal + San d\'Or. Flour (Komalata, Tavnazian Safehold, 60 gil), Selbina Butter (Kopopo, Windurst Waters, 300 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil)\n• Garlic Cracker (cap 49): Fire Crystal + Mhaura Garlic (Ahyeekih, Windurst Waters, 84 gil), Tarutaru Rice (Kopopo, Windurst Waters, 300 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)' },
            { title = 'Cooking 50–60', note = '• Crayfish Ball (cap 52): Earth Crystal + San d\'Or. Flour (Komalata, Tavnazian Safehold, 60 gil), 3 × Crayfish (Kulh Amariyo, Aht Urhgan Whitegate, 38 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Egg Soup (cap 57): Fire Crystal + Black Pepper (Amalasanda, Lower Jeuno, 255 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Bird Egg (Denvihr, Port Bastok, 55 gil)\n• Spicy Cracker (cap 59): Fire Crystal + Kazham Peppers (Ghemi Sinterilo, Kazham, 60 gil), Tarutaru Rice (Kopopo, Windurst Waters, 300 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Beaugr. Saute (cap 55): Fire Crystal + Selbina Butter (Kopopo, Windurst Waters, 300 gil), Beaugreens (Rodellieux, Bastok Mines, 105 gil)' },
            { title = 'Cooking 60–70', note = '• Stone Cheese (cap 61): Dark Crystal + Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Selbina Milk (Dohdjuma, Selbina, 61 gil)\n• Colored Egg (cap 68): Fire Crystal + La Theine Cbg. (Aveline, Southern San d\'Oria, 24 gil), San d\'Or. Carrot (Komalata, Tavnazian Safehold, 32 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil), Bird Egg (Denvihr, Port Bastok, 55 gil)\n• San d\'Orian Tea (cap 70): Fire Crystal + Maple Sugar (Benaige, Southern San d\'Oria, 40 gil), Win. Tea Leaves (Baehu-Faehu, Windurst Waters, 20 gil), Sage (Aveline, Southern San d\'Oria, 185 gil), Selbina Milk (Dohdjuma, Selbina, 61 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)\n• Pumpkin Soup (cap 65): Fire Crystal + Ogre Pumpkin (Fomina, Windurst Waters, 99 gil), Sage (Aveline, Southern San d\'Oria, 185 gil), Rock Salt (Benaige, Southern San d\'Oria, 15 gil), Selbina Milk (Dohdjuma, Selbina, 61 gil), Distilled Water (Benaige, Southern San d\'Oria, 12 gil)' },
